require 'webrick'
require 'fluent/log'

module Fluent
  module RPC
    class Server
      def initialize(endpoint, log)
        bind, port = endpoint.split(':')
        @bind = bind
        @port = port
        @log = log

        @server = WEBrick::HTTPServer.new(
          BindAddress: @bind,
          Port: @port,
          Logger: WEBrick::Log.new(STDERR, WEBrick::Log::FATAL),
          AccessLog: [],
        )
      end

